from typing import List
class Solution:
    def maxBalancedSubsequenceSum(self, nums: List[int]) -> int:
        n = len(nums)
        b = sorted(set(nums[i] - i for i in range(n)))
        rank = {v: i + 1 for i, v in enumerate(b)}
        m = len(b)
        tree = [float('-inf')] * (m + 1)
        def update(i, v):
            while i <= m:
                tree[i] = max(tree[i], v)
                i += i & (-i)
        def query(i):
            res = float('-inf')
            while i > 0:
                res = max(res, tree[i])
                i -= i & (-i)
            return res
        ans = float('-inf')
        for i in range(n):
            r = rank[nums[i] - i]
            dp = nums[i] + max(0, query(r)) if query(r) != float('-inf') else nums[i]
            dp = nums[i] + max(query(r), 0)
            ans = max(ans, dp)
            update(r, dp)
        return ans

