class Solution {
public:
    long long maxBalancedSubsequenceSum(vector<int>& nums) {
        int n = nums.size();
        vector<long long> b(n);
        for (int i = 0; i < n; ++i) b[i] = (long long)nums[i] - i;
        vector<long long> vals = b;
        sort(vals.begin(), vals.end());
        vals.erase(unique(vals.begin(), vals.end()), vals.end());
        int m = vals.size();
        vector<long long> tree(m + 1, LLONG_MIN);
        auto update = [&](int i, long long v) {
            for (; i <= m; i += i & (-i)) tree[i] = max(tree[i], v);
        };
        auto query = [&](int i) {
            long long res = LLONG_MIN;
            for (; i > 0; i -= i & (-i)) res = max(res, tree[i]);
            return res;
        };
        long long ans = LLONG_MIN;
        for (int i = 0; i < n; ++i) {
            int r = lower_bound(vals.begin(), vals.end(), b[i]) - vals.begin() + 1;
            long long prev = query(r);
            long long dp = nums[i] + (prev == LLONG_MIN ? 0 : max(prev, 0LL));
            ans = max(ans, dp);
            update(r, dp);
        }
        return ans;
    }
};

