class Solution {
    public long maxBalancedSubsequenceSum(int[] nums) {
        int n = nums.length;
        long[] b = new long[n];
        for (int i = 0; i < n; ++i) b[i] = (long) nums[i] - i;
        long[] vals = b.clone();
        java.util.Arrays.sort(vals);
        int m = 0;
        for (int i = 0; i < n; ++i) if (i == 0 || vals[i] != vals[m-1]) vals[m++] = vals[i];
        long[] tree = new long[m + 1];
        java.util.Arrays.fill(tree, Long.MIN_VALUE);
        java.util.function.BiConsumer<Integer, Long> update = (i, v) -> {
            for (; i <= m; i += i & (-i)) tree[i] = Math.max(tree[i], v);
        };
        java.util.function.IntFunction<Long> query = i -> {
            long res = Long.MIN_VALUE;
            for (; i > 0; i -= i & (-i)) res = Math.max(res, tree[i]);
            return res;
        };
        long ans = Long.MIN_VALUE;
        for (int i = 0; i < n; ++i) {
            int lo = 0, hi = m - 1;
            while (lo < hi) { int mid = (lo + hi) >>> 1; if (vals[mid] < b[i]) lo = mid + 1; else hi = mid; }
            long prev = query.apply(lo + 1);
            long dp = nums[i] + (prev == Long.MIN_VALUE ? 0 : Math.max(prev, 0L));
            ans = Math.max(ans, dp);
            update.accept(lo + 1, dp);
        }
        return ans;
    }
}

