class Solution:
    def maxBalancedSubsequenceSum(self, nums):
        n = len(nums)
        b = sorted(set(x - i for i, x in enumerate(nums)))
        rk = {v: i for i, v in enumerate(b)}
        m = len(b)
        tree = [float('-inf')] * (2 * m)
        def update(pos, val):
            pos += m
            tree[pos] = max(tree[pos], val)
            pos >>= 1
            while pos:
                tree[pos] = max(tree[2*pos], tree[2*pos+1])
                pos >>= 1
        def query(l, r):
            res = float('-inf'); l += m; r += m + 1
            while l < r:
                if l & 1: res = max(res, tree[l]); l += 1
                if r & 1: r -= 1; res = max(res, tree[r])
                l >>= 1; r >>= 1
            return res
        ans = float('-inf')
        for i, x in enumerate(nums):
            p = rk[x - i]
            prev = query(0, p)
            dp = x + max(prev, 0)
            ans = max(ans, dp)
            update(p, dp)
        return ans

