class Solution {
    vector<long long> tree; int m;
public:
    long long maxBalancedSubsequenceSum(vector<int>& nums) {
        int n = nums.size();
        vector<long long> b(n);
        for (int i = 0; i < n; ++i) b[i] = (long long)nums[i] - i;
        vector<long long> v = b;
        sort(v.begin(), v.end()); v.erase(unique(v.begin(), v.end()), v.end());
        m = v.size(); tree.assign(2 * m, LLONG_MIN);
        auto upd = [&](int p, long long val) {
            p += m; tree[p] = max(tree[p], val);
            for (p >>= 1; p; p >>= 1) tree[p] = max(tree[2*p], tree[2*p+1]);
        };
        auto qry = [&](int l, int r) {
            long long res = LLONG_MIN;
            for (l += m, r += m + 1; l < r; l >>= 1, r >>= 1) {
                if (l & 1) res = max(res, tree[l++]);
                if (r & 1) res = max(res, tree[--r]);
            }
            return res;
        };
        long long ans = LLONG_MIN;
        for (int i = 0; i < n; ++i) {
            int p = lower_bound(v.begin(), v.end(), b[i]) - v.begin();
            long long prev = qry(0, p);
            long long dp = nums[i] + (prev == LLONG_MIN ? 0 : max(prev, 0LL));
            ans = max(ans, dp); upd(p, dp);
        }
        return ans;
    }
};

