class Solution {
    public long maxBalancedSubsequenceSum(int[] nums) {
        int n = nums.length;
        long[] b = new long[n];
        for (int i = 0; i < n; ++i) b[i] = (long) nums[i] - i;
        long[] v = b.clone();
        java.util.Arrays.sort(v);
        int m = 0;
        for (int i = 0; i < n; ++i) if (i == 0 || v[i] != v[m-1]) v[m++] = v[i];
        long[] tree = new long[2 * m];
        java.util.Arrays.fill(tree, Long.MIN_VALUE);
        long ans = Long.MIN_VALUE;
        for (int i = 0; i < n; ++i) {
            int lo = 0, hi = m - 1;
            while (lo < hi) { int mid = (lo + hi) >>> 1; if (v[mid] < b[i]) lo = mid + 1; else hi = mid; }
            int l = lo + m, r = m - 1 + m;
            long prev = Long.MIN_VALUE;
            while (l <= r) {
                if ((l & 1) == 1) prev = Math.max(prev, tree[l++]);
                if ((r & 1) == 0) prev = Math.max(prev, tree[r--]);
                l >>= 1; r >>= 1;
            }
            long dp = nums[i] + (prev == Long.MIN_VALUE ? 0 : Math.max(prev, 0L));
            ans = Math.max(ans, dp);
            int p = lo + m;
            tree[p] = Math.max(tree[p], dp);
            for (p >>= 1; p > 0; p >>= 1) tree[p] = Math.max(tree[2*p], tree[2*p+1]);
        }
        return ans;
    }
}

